cd /app && python3 << 'EOF'
import torch

weights = torch.load('weights.pt')
all_keys = sorted(weights.keys())

print("Total layers:", len(all_keys))
print("\nGrouped by component:")

# Count unique prefixes
prefixes = {}
for k in all_keys:
    prefix = k.split('.')[0]
    if prefix not in prefixes:
        prefixes[prefix] = []
    prefixes[prefix].append(k)

for prefix in sorted(prefixes.keys()):
    print(f"\n{prefix}: {len(prefixes[prefix])} entries")
    if len(prefixes[prefix]) <= 5:
        for k in prefixes[prefix]:
            v = weights[k]
            print(f"  {k}: {v.shape}")
    else:
        print(f"  (showing first and last 2)")
        for k in prefixes[prefix][:2]:
            v = weights[k]
            print(f"  {k}: {v.shape}")
        print(f"  ...")
        for k in prefixes[prefix][-2:]:
            v = weights[k]
            print(f"  {k}: {v.shape}")
